'use strict';
P.FX={
pixel(ctx,x,y,size,color){ctx.fillStyle=color;ctx.fillRect(Math.round(x-size/2),Math.round(y-size/2),size,size)},
trail(ctx,points,color){if(!points)return;ctx.fillStyle=color;for(let i=0;i<points.length;i++){const size=3+i/3;ctx.globalAlpha=(i+1)/points.length*.45;ctx.fillRect(Math.round(points[i].x-size/2),Math.round(points[i].y-size/2),size,size)}ctx.globalAlpha=1},
// Rasterize the complete glow and geometry once; motion and trails stay live.
glyphCache:new Map(),cachePixels:0,maxCachePixels:4194304,
glyphBounds:{MIC:[-10,-13,20,32],FAN:[-21,-27,42,36],KEY:[-22,-11,44,22],PHONE:[-10,-15,20,30],PAD:[-21,-10,42,24],PLUMA:[-17,-7,34,14],FISH:[-17,-11,32,21],BULLET:[-40,-6,56,14],BANANA:[-15,-13,32,26],BCP:[-17,-11,34,23],DIAPER:[-18,-9,36,21],PIG:[-15,-13,32,26],PIG_WING:[-25,-15,42,30],ICE:[-11,-9,25,18],ZIG:[-16,-10,32,20],PULSE:[-12,-6,27,12],ORB:[-8,-8,16,16],FEATHER:[-16,-7,34,14],ROACH:[-12,-11,32,22]},
cacheable(s){return s.kind!=='stomp'&&['MIC','FAN','KEY','PHONE','PAD','PLUMA','FISH','BULLET','BANANA','BCP','DIAPER','PIG','PIG_WING','ICE','ZIG','PULSE','ORB','FEATHER','ROACH'].includes(s.glyph)},
cachedGlyph(ctx,s){if(typeof s.color!=='string'||!this.cacheable(s)||P.Performance?.active&&P.Performance.legacyRendering||typeof document==='undefined')return false;const matrix=this.rasterScale?null:ctx.getTransform?.(),rawScale=this.rasterScale||(matrix?Math.hypot(matrix.a,matrix.b):0),scale=Math.round(rawScale*1000)/1000;if(!(scale>0))return false;const phase=s.glyph==='ROACH'?Math.floor(s.age*22)%2:0,key=[s.glyph,s.color,!!s.ultimate,phase,scale].join('|');let entry=this.glyphCache.get(key);if(!entry){const bounds=this.glyphBounds[s.glyph],width=Math.ceil(bounds[2]*scale)+48,height=Math.ceil(bounds[3]*scale)+48,pixels=width*height;if(pixels>this.maxCachePixels)return false;const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const g=canvas.getContext('2d');if(!g)return false;const originX=24-Math.floor(bounds[0]*scale),originY=24-Math.floor(bounds[1]*scale);g.setTransform(scale,0,0,scale,originX,originY);g.imageSmoothingEnabled=false;g.textAlign='center';this.glyph(g,s);entry={canvas,originX,originY,scale,pixels};while(this.glyphCache.size&&(this.cachePixels+pixels>this.maxCachePixels||this.glyphCache.size>=96)){const oldest=this.glyphCache.keys().next().value;this.cachePixels-=this.glyphCache.get(oldest).pixels;this.glyphCache.delete(oldest)}this.glyphCache.set(key,entry);this.cachePixels+=pixels}ctx.shadowBlur=0;ctx.drawImage(entry.canvas,-entry.originX/entry.scale,-entry.originY/entry.scale,entry.canvas.width/entry.scale,entry.canvas.height/entry.scale);return true},
projectile(ctx,s){if(s.tactical&&P.MinionTactics?.draw(ctx,s))return;if(s.busTicket){P.ChosicanoArt.ticket(ctx,s);return}if(s.hornWave){P.ChosicanoArt.horn(ctx,s);return}if(s.congress){this.congress(ctx,s);return}this.trail(ctx,s.history,s.color);ctx.save();ctx.translate(Math.round(s.x),Math.round(s.y));ctx.rotate(s.kind==='boomerang'?s.age*13:Math.atan2(s.vy,s.vx));if(s.evolution){ctx.strokeStyle=s.color;ctx.lineWidth=2;ctx.strokeRect(-18,-10,36,20)}if(!this.cachedGlyph(ctx,s))this.glyph(ctx,s);P.MinionEvolution?.projectileFX(ctx,s);ctx.restore()},
congress(ctx,s){const palettes=[['#262b42','#d6a078','#7a3047'],['#35313d','#b97856','#31597a'],['#202b35','#e0b18a','#596b38']],p=palettes[s.congressVariant%palettes.length],bounce=Math.sin(s.age*13)*2;this.trail(ctx,s.history,p[2]);ctx.save();ctx.translate(Math.round(s.x),Math.round(s.y+bounce));ctx.rotate(Math.atan2(s.vy,s.vx)+Math.PI/2+Math.sin(s.age*9)*.08);ctx.shadowColor='#ffba6e';ctx.shadowBlur=6;ctx.fillStyle='#171724';ctx.fillRect(-7,-17,14,5);ctx.fillStyle=p[1];ctx.fillRect(-6,-13,12,9);ctx.fillStyle='#211c20';ctx.fillRect(-5,-14,10,3);ctx.fillStyle=p[0];ctx.fillRect(-9,-4,18,16);ctx.fillRect(-13,-2,5,12);ctx.fillRect(8,-2,5,12);ctx.fillRect(-8,12,6,10);ctx.fillRect(2,12,6,10);ctx.fillStyle='#f4e4cb';ctx.fillRect(-3,-4,6,10);ctx.fillStyle=p[2];ctx.fillRect(-1,-2,3,9);ctx.fillStyle='#fff2c7';ctx.fillRect(-3,-10,2,2);ctx.fillRect(2,-10,2,2);ctx.restore()},
glyph(ctx,s){if(P.MinionProfessions?.glyph(ctx,s))return;if(s.theme){P.MinionEvolution.drawMelee(ctx,s);return}ctx.shadowColor=s.color;ctx.shadowBlur=s.ultimate?0:8;
if(P.PowerFX.projectile(ctx,s))return;
if(s.glyph==='CONE'){ctx.shadowBlur=0;ctx.fillStyle='#392f31';ctx.fillRect(-12,6,24,5);ctx.fillStyle='#f58c36';ctx.beginPath();ctx.moveTo(0,-17);ctx.lineTo(-9,6);ctx.lineTo(9,6);ctx.closePath();ctx.fill();ctx.fillStyle='#fff0cd';ctx.fillRect(-4,-5,8,4)}else if(s.glyph==='SHARD'){ctx.shadowBlur=0;ctx.fillStyle='#6f382a';ctx.beginPath();ctx.moveTo(-11,4);ctx.lineTo(-3,-10);ctx.lineTo(10,-2);ctx.lineTo(4,9);ctx.closePath();ctx.fill();ctx.fillStyle='#ddb17b';ctx.fillRect(-3,-5,5,9);ctx.fillStyle='#67ad9e';ctx.fillRect(1,-2,5,3)}else if(s.glyph==='FEATHER'){ctx.shadowBlur=0;ctx.fillStyle='#222b39';ctx.beginPath();ctx.moveTo(-14,0);ctx.lineTo(-7,-5);ctx.lineTo(3,-5);ctx.lineTo(15,0);ctx.lineTo(4,5);ctx.lineTo(-7,4);ctx.closePath();ctx.fill();ctx.fillStyle='#718293';ctx.fillRect(-7,-4,10,2);ctx.fillStyle='#cfc8a6';ctx.fillRect(-14,-1,30,2);ctx.strokeStyle='#9ca9ae';ctx.lineWidth=1;for(let i=-7;i<8;i+=4){ctx.beginPath();ctx.moveTo(i,0);ctx.lineTo(i-3,-3);ctx.stroke()}}
else if(s.kind==='stomp'){ctx.strokeStyle=s.color;ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(0,0,s.radius*(.5+Math.min(1,s.age/.2)*.5),s.radius*(.5+Math.min(1,s.age/.2)*.5),0,0,Math.PI*2);ctx.stroke()}
else if(s.glyph==='ICE'){ctx.fillStyle=s.color;ctx.beginPath();ctx.moveTo(11,0);ctx.lineTo(0,-6);ctx.lineTo(-8,0);ctx.lineTo(0,6);ctx.closePath();ctx.fill();ctx.fillStyle='#fff';ctx.fillRect(-3,-1,11,2)}
else if(s.glyph==='STAR'){ctx.rotate(s.age*8);ctx.fillStyle=s.color;ctx.beginPath();for(let i=0;i<10;i++){const r=i%2?3:8,a=i*Math.PI/5;ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r)}ctx.closePath();ctx.fill()}
else if(s.glyph==='ZIG'){ctx.strokeStyle=s.color;ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-10,-4);ctx.lineTo(-2,3);ctx.lineTo(3,-3);ctx.lineTo(10,3);ctx.stroke()}
else if(s.glyph==='PULSE'){ctx.fillStyle=s.color;ctx.fillRect(-10,-3,20,6);this.pixel(ctx,7,0,5,'#f3fff0')}
else if(s.glyph==='ORB'){ctx.fillStyle=s.color;ctx.beginPath();ctx.arc(0,0,6,0,Math.PI*2);ctx.fill();this.pixel(ctx,-1,-1,4,'#fff3ce')}
else if(s.glyph==='MIC'){ctx.fillStyle='#182132';ctx.fillRect(-7,-10,14,20);ctx.fillStyle='#d1dce5';ctx.fillRect(-6,-10,12,9);ctx.fillStyle='#90a4b5';for(let i=0;i<3;i++)ctx.fillRect(-5,-9+i*3,10,1);ctx.fillStyle='#53697b';ctx.fillRect(-3,2,6,13)}
else if(s.glyph==='FAN'){for(let i=0;i<5;i++){ctx.save();ctx.rotate((i-2)*.32);ctx.fillStyle=i%2?'#ffc078':'#ed843b';ctx.fillRect(-3,-23,6,26);ctx.restore()}this.pixel(ctx,0,2,5,'#fff1bb')}
else if(s.glyph==='CARD'){ctx.fillStyle='#694b35';ctx.fillRect(-12,-9,24,18);ctx.fillStyle='#f6e4bf';ctx.fillRect(-10,-7,20,14);ctx.fillStyle='#bc6e58';ctx.fillRect(3,-5,5,5);ctx.fillStyle='#8e7b65';for(let i=0;i<3;i++)ctx.fillRect(-7,-4+i*4,8,1)}
else if(s.glyph==='KEY'){ctx.fillStyle='#1a2333';ctx.fillRect(-20,-9,40,18);for(let y=0;y<3;y++)for(let x=0;x<8;x++)this.pixel(ctx,-16+x*4.5,-5+y*4,3,(x+y)%2?'#6bd9e7':'#b59afa')}
else if(s.glyph==='PHONE'){ctx.fillStyle='#172236';ctx.fillRect(-8,-13,16,26);ctx.fillStyle='#87d8c9';ctx.fillRect(-6,-10,12,18);ctx.fillStyle='#eff7e7';ctx.fillRect(-2,10,4,2)}
else if(s.glyph==='PAD'){ctx.fillStyle='#34304e';ctx.fillRect(-16,-8,32,16);ctx.fillRect(-19,-2,7,13);ctx.fillRect(12,-2,7,13);ctx.fillStyle='#d8c4ff';ctx.fillRect(-11,-5,3,10);ctx.fillRect(-14,-2,9,3);this.pixel(ctx,10,-2,4,'#e9acac');this.pixel(ctx,6,3,4,'#a8dbc4')}
else if(s.glyph==='PLUMA'){for(let i=0;i<5;i++)this.pixel(ctx,-12+i*5,Math.sin(i)*3,6-i*.7,s.color);ctx.fillStyle='#e7ece5';ctx.fillRect(-12,-1,25,2)}
else{ctx.fillStyle='#332b59';ctx.fillRect(-11,-11,22,22);ctx.fillStyle=s.color;ctx.fillRect(-9,-9,18,18);ctx.fillStyle='#fff1c5';ctx.fillRect(-5,-4,3,3);ctx.fillRect(3,-4,3,3);ctx.fillRect(-4,3,10,2)}
},
orbit(ctx,p){const points=P.Combat.orbitPoints(p,P.state.elapsed);ctx.save();ctx.strokeStyle='#edb26b55';ctx.lineWidth=1;ctx.setLineDash([3,9]);ctx.beginPath();ctx.ellipse(p.x,p.y,100*p.reach,100*p.reach,0,0,7);ctx.stroke();ctx.setLineDash([]);for(let i=0;i<points.length;i++){const o=points[i],a=P.state.elapsed*2.8+i*Math.PI*2/points.length;for(let j=8;j>0;j--){ctx.globalAlpha=(1-j/9)*.35;const t=a-j*.045;this.pixel(ctx,p.x+Math.cos(t)*100*p.reach,p.y+Math.sin(t)*100*p.reach,6,'#edb26b')}ctx.globalAlpha=1;ctx.save();ctx.translate(o.x,o.y);ctx.rotate(a+Math.PI/2);for(let k=-3;k<=3;k++){ctx.fillStyle=k%3===0?'#f4ead3':'#e76b5d';ctx.fillRect(k*5,-7+Math.sin(P.state.elapsed*12+k)*3,5,14)}ctx.restore()}ctx.restore()},
effect(ctx,e){const progress=1-e.life/e.maxLife;ctx.save();ctx.globalAlpha=Math.min(1,e.life/e.maxLife*2);
if(e.kind==='mini-counter'||e.kind==='mini-impact'){P.Minibosses.feedback(ctx,e,progress);ctx.restore();return}if(e.kind==='miniboss-death'){P.Minibosses.draw(ctx,e,Math.max(.001,progress));ctx.restore();return}if(e.kind==='minion-hit'||e.kind==='minion-death'){P.EnemyArt.feedbackDraw(ctx,e,progress);ctx.restore();return}
if(e.kind==='feather-break'){ctx.translate(e.x,e.y);ctx.rotate(e.angle);for(let i=0;i<5;i++){const sign=i%2?1:-1,d=5+progress*(14+i*3);ctx.fillStyle=i%2?'#b0b9b7':'#394657';ctx.save();ctx.translate(-progress*12+i*2,sign*d*.65);ctx.rotate(sign*(.3+progress*2));ctx.fillRect(-2,-4,3,i%2?6:9);ctx.restore()}ctx.restore();return}
if(e.kind==='evolution'){P.Evolutions?.effect(ctx,e,progress);ctx.restore();return}
if(P.PowerFX.effect(ctx,e,progress)){ctx.restore();return}
if(e.kind==='spark'){this.pixel(ctx,e.x,e.y,4,e.color)}
else if(e.kind==='damage'){ctx.fillStyle='#fff1bc';ctx.font='bold 12px monospace';ctx.textAlign='center';ctx.fillText(e.text,e.x,e.y-progress*26)}
else if(e.kind==='cast'){for(let i=0;i<6;i++){const a=i*Math.PI/3+progress*2;this.pixel(ctx,e.x+Math.cos(a)*(8+progress*20),e.y+Math.sin(a)*(8+progress*20),4,e.color)}}
else if(e.kind==='impact'){ctx.strokeStyle=e.color;ctx.lineWidth=3;for(let i=0;i<6;i++){const a=i*Math.PI/3;ctx.beginPath();ctx.moveTo(e.x+Math.cos(a)*(3+progress*5),e.y+Math.sin(a)*(3+progress*5));ctx.lineTo(e.x+Math.cos(a)*(10+progress*15),e.y+Math.sin(a)*(10+progress*15));ctx.stroke()}}
else if(e.kind==='nova'){for(let i=0;i<3;i++){const step=Math.max(0,progress-i*.12),radius=e.r*step;ctx.strokeStyle=i===0?'#fff0c5':e.color;ctx.lineWidth=4-i;ctx.beginPath();for(let j=0;j<=48;j++){const a=j*Math.PI/24,x=e.x+Math.cos(a)*radius,y=e.y+Math.sin(a)*radius;j?ctx.lineTo(Math.round(x/3)*3,Math.round(y/3)*3):ctx.moveTo(x,y)}ctx.stroke()}for(let i=0;i<12;i++){const a=i*Math.PI/6;this.pixel(ctx,e.x+Math.cos(a)*e.r*progress,e.y+Math.sin(a)*e.r*progress,5,e.color)}}
else if(e.kind==='cone'){for(let i=0;i<4;i++){const t=Math.max(0,progress-i*.13),radius=e.r*t;if(!radius)continue;ctx.strokeStyle=i%2?'#fff0c5':e.color;ctx.lineWidth=5-i;ctx.beginPath();ctx.arc(e.x,e.y,radius,e.angle-.65,e.angle+.65);ctx.stroke()}ctx.globalAlpha=.08*(1-progress);ctx.fillStyle=e.color;ctx.beginPath();ctx.moveTo(e.x,e.y);ctx.arc(e.x,e.y,e.r,e.angle-.65,e.angle+.65);ctx.closePath();ctx.fill()}
ctx.restore()}
};
